import { useState } from 'react'
import { Trophy, TrendingUp, Star, Eye, CalendarDays, Flame } from 'lucide-react'
import { useCatalog } from '../lib/catalog-context'
import { trending, topRanked, mostPopular, newestSeries } from '../lib/selectors'
import { RankRow } from '../components/SeriesCard'
import { SectionHeader, Button } from '../components/ui'
import { navigate } from '../lib/router'
import { cx, formatViews, seriesHref } from '../lib/utils'
import type { WeekDay } from '../types'

const WEEK: WeekDay[] = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']

type BoardKey = 'trending' | 'rating' | 'views' | 'newest'

const BOARDS: { key: BoardKey; label: string; icon: typeof Trophy; desc: string }[] = [
  { key: 'trending', label: 'Trending Now', icon: Flame, desc: 'Most read, bookmarked, and acclaimed series.' },
  { key: 'rating', label: 'Highest Rated', icon: Star, desc: 'All-time community rating leaders.' },
  { key: 'views', label: 'Most Popular', icon: Eye, desc: 'Lifetime view leaders across the platform.' },
  { key: 'newest', label: 'New Arrivals', icon: TrendingUp, desc: 'The freshest debuts on MANHWAS.' },
]

export default function Rankings() {
  const { series: catalog, loading } = useCatalog()
  const [board, setBoard] = useState<BoardKey>('trending')
  // render the top 100 per board — the full ~2,100-row list made every
  // board switch a 1-2s freeze
  const [shown, setShown] = useState(100)

  const list = loading
    ? []
    : board === 'trending'
      ? trending(catalog)
      : board === 'rating'
        ? topRanked(catalog)
        : board === 'views'
          ? mostPopular(catalog)
          : newestSeries(catalog)

  const metric = (i: number) => {
    const s = list[i]
    switch (board) {
      case 'rating':
        return `★ ${s.rating.toFixed(1)} (${formatViews(s.ratingCount)})`
      case 'views':
        return `${formatViews(s.views)} views`
      case 'newest':
        return `Debuted ${new Date(s.firstReleased).getFullYear()}`
      default:
        return `${formatViews(s.weeklyViews)} this week`
    }
  }

  // Weekly drop schedule distribution
  const schedule = WEEK.map((day) => ({
    day,
    count: catalog.filter((s) => s.schedule === day).length,
  }))
  const maxCount = Math.max(...schedule.map((s) => s.count), 1)

  const podium = list.slice(0, 3)

  return (
    <main className="mx-auto max-w-[1240px] animate-fade-up px-4 py-10 sm:px-6 lg:px-8">
      <div className="mb-8">
        <div className="eyebrow mb-2 text-accent">Leaderboards</div>
        <h1 className="text-3xl font-extrabold tracking-tight sm:text-4xl">Platform Rankings</h1>
        <p className="mt-2 max-w-xl text-ink-soft">
          Most read, bookmarked, and acclaimed series — updated as chapters go live.
        </p>
      </div>

      {/* Board tabs */}
      <div className="mb-8 flex flex-wrap gap-2">
        {BOARDS.map((b) => (
          <button
            key={b.key}
            onClick={() => { setBoard(b.key); setShown(100) }}
            className={cx(
              'inline-flex items-center gap-2 rounded-full border px-4 py-2 text-sm font-semibold transition-colors',
              board === b.key
                ? 'border-ink bg-ink text-paper'
                : 'border-line-strong bg-paper text-ink-soft hover:border-ink hover:text-ink',
            )}
          >
            <b.icon width={15} height={15} />
            {b.label}
          </button>
        ))}
      </div>

      {/* Podium */}
      {loading ? (
        <div className="mb-10 grid gap-4 sm:grid-cols-3">
          {Array.from({ length: 3 }).map((_, i) => (
            <div key={i} className="h-[148px] animate-pulse rounded-[18px] bg-paper-3/60" />
          ))}
        </div>
      ) : (
        <div className="mb-10 grid gap-4 sm:grid-cols-3">
          {podium.map((s, i) => (
            <div
              key={s.id}
              className={cx(
                'relative overflow-hidden rounded-[18px] border p-5 transition-transform hover:-translate-y-1',
                i === 0 ? 'border-accent/40 bg-gradient-to-br from-accent/10 to-transparent' : 'border-line bg-paper',
              )}
            >
              <div className="flex items-center justify-between">
                <span
                  className={cx(
                    'grid h-9 w-9 place-items-center rounded-full text-sm font-black',
                    i === 0 ? 'bg-accent text-white' : 'bg-ink text-paper',
                  )}
                >
                  {i + 1}
                </span>
                <Trophy width={18} height={18} className={i === 0 ? 'text-accent' : 'text-ink-faint'} />
              </div>
              <button
                onClick={() => navigate(`${seriesHref(s)}`)}
                className="mt-4 text-left text-lg font-extrabold leading-tight tracking-tight hover:text-accent"
              >
                {s.title}
              </button>
              <p className="mt-1 text-xs text-ink-faint">{s.author} · {s.genres[0]}</p>
              <p className="mt-3 text-sm font-bold tabular-nums">{metric(i)}</p>
            </div>
          ))}
        </div>
      )}

      <div className="grid gap-10 lg:grid-cols-[1fr_340px]">
        {/* Main board */}
        <section>
          <SectionHeader
            eyebrow="Full Leaderboard"
            title={BOARDS.find((b) => b.key === board)!.label}
          />
          <p className="-mt-3 mb-4 text-sm text-ink-faint">
            {BOARDS.find((b) => b.key === board)!.desc}
          </p>
          {loading ? (
            <div className="overflow-hidden rounded-[16px] border border-line bg-paper">
              {Array.from({ length: 10 }).map((_, i) => (
                <div key={i} className={i > 0 ? 'border-t border-line' : ''}>
                  <div className="m-3 h-14 animate-pulse rounded-lg bg-paper-3/60" />
                </div>
              ))}
            </div>
          ) : (
            <>
              <div className="overflow-hidden rounded-[16px] border border-line bg-paper">
                {list.slice(0, shown).map((s, i) => (
                  <div key={s.id} className={i > 0 ? 'border-t border-line' : ''}>
                    <RankRow series={s} rank={i + 1} metric={metric(i)} />
                  </div>
                ))}
              </div>
              {shown < list.length && (
                <button
                  onClick={() => setShown((n) => n + 100)}
                  className="mt-6 w-full rounded-full border border-line-strong bg-paper px-6 py-2.5 text-sm font-bold text-ink transition-colors hover:border-ink"
                >
                  Show more ({list.length - shown} remaining)
                </button>
              )}
            </>
          )}
        </section>

        {/* Side column */}
        <aside className="space-y-6">
          {/* Weekly drop schedule */}
          <div className="rounded-[16px] border border-line bg-paper p-5">
            <div className="flex items-center gap-2">
              <CalendarDays width={16} height={16} className="text-accent" />
              <h3 className="text-sm font-extrabold tracking-tight">Weekly Drop Schedule</h3>
            </div>
            <p className="mt-1 text-xs text-ink-faint">Release days across the catalog</p>
            <div className="mt-5 space-y-2.5">
              {schedule.map(({ day, count }) => (
                <div key={day} className="flex items-center gap-3">
                  <span className="w-9 shrink-0 text-[11px] font-bold uppercase tracking-wide text-ink-faint">
                    {day.slice(0, 3)}
                  </span>
                  <div className="h-2.5 flex-1 overflow-hidden rounded-full bg-paper-3">
                    <div
                      className="h-full rounded-full bg-ink transition-all"
                      style={{ width: `${(count / maxCount) * 100}%` }}
                    />
                  </div>
                  <span className="w-6 text-right text-xs font-bold tabular-nums text-ink-soft">
                    {count}
                  </span>
                </div>
              ))}
            </div>
          </div>

          {/* Release calendar preview */}
          <div className="rounded-[16px] border border-line bg-paper p-5">
            <h3 className="text-sm font-extrabold tracking-tight">Release Calendar</h3>
            <p className="mt-1 text-xs text-ink-faint">This week's drop days</p>
            <div className="mt-4 space-y-2">
              {WEEK.map((day) => {
                const drops = catalog.filter((s) => s.schedule === day).length
                return (
                  <div key={day} className="flex items-center justify-between rounded-lg bg-paper-2/60 px-3 py-2">
                    <span className="text-xs font-semibold text-ink-soft">{day}</span>
                    <span className={cx('text-xs font-bold', drops > 0 ? 'text-accent' : 'text-ink-faint')}>
                      {drops > 0 ? `${drops} series` : '—'}
                    </span>
                  </div>
                )
              })}
            </div>
          </div>

          <div className="rounded-[16px] bg-[#151513] p-5 text-white">
            <div className="eyebrow text-accent">Publishing</div>
            <h3 className="mt-2 text-base font-extrabold tracking-tight">Creator Submissions</h3>
            <p className="mt-2 text-sm text-white/65">
              Studios and independent artists can submit new series to the editorial desk.
            </p>
            <div className="mt-4">
              <Button
                size="sm"
                onClick={() => navigate('/admin')}
                className="bg-accent hover:bg-accent-dark"
              >
                Open Admin Portal
              </Button>
            </div>
          </div>
        </aside>
      </div>
    </main>
  )
}
